function OverseaManagePersonnelRoleCell:RefreshChooseStatus(isIn,index)
    self:SetChooseStatus(isIn)
    if isIn then
        CfUtils.FillText(self.ChoosePosText,index)
    end
end

function OverseaManagePersonnelRoleCell:RefreshRoleData(data,callBack)
    self.callBack = callBack
    self.data = data
    self:SetHeadNode()
    self:SetSoulPoint()
end

function OverseaManagePersonnelRoleCell:SetChooseStatus(status)
    KTool.SetActive(self.Choose.gameObject,status)
end

function OverseaManagePersonnelRoleCell:SetSelectStatus(status)
    KTool.SetActive(self.ImgSelect.gameObject,status)
end

function OverseaManagePersonnelRoleCell:SetSoulPoint()
    local curPoint = tonumber(self.data.cafeEnergy) or 0

    KTool.SetActive(self.ImgMask2.gameObject,curPoint == 0)

    local vo = MaidCoffeeUtils.GetCardManagerInfoVo(tonumber(self.data.cardId))
    KTool.SetActive(self.BuffIcon.gameObject,vo.additionId > 0)
    if vo.additionId > 0 then
        local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(vo.additionId)
        if skillVo then
            CfUtils.FillImage(self.ImgIcon,skillVo.icon)
        end
    end
    self:RefreshWorkStatus()
    local level = tonumber(self.data.favorabilityLevel)
    local curMood = MaidCoffeeUtils.GetCurMoodByCardFavorabilityLevel(self.data.cardId,level)
    local maxPoint = curMood
    CfUtils.FillText(self.SoulPoint,curPoint)
    self.Slider.value = curPoint/maxPoint
    MaidCoffeeUtils.FillSoulImage(self.ImgAttribute,curPoint)
end

function OverseaManagePersonnelRoleCell:RefreshWorkStatus()
    KTool.SetActive(self.ImgState.gameObject,self.data.cafeStatus ~= 0)
    if self.data.cafeStatus ~= 0 then
        MaidCoffeeUtils.FillWorkImgStatus(self.TxtState,self.ImgState,self.data.cafeStatus,false)
    end
end

function OverseaManagePersonnelRoleCell:SetHeadNode()
    ---@type Engine.Modules.LuaBehaviour
    local headNode = GetLuaBehaviour(self.CommonSmallHeadNode.gameObject, CardHeadNodePath)
    if isNull(headNode.Env) then
        headNode:Init()
    end
--[[    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById()]]
    headNode.Env:FreshNode(self.data)
    headNode.Env:SetRookieStatus(true)
    headNode.Env:SetCallBack(function(id)
        ---点击的事件执行
        if self.callBack then
            self.callBack(false)
        end
    end)

end

function OverseaManagePersonnelRoleCell:Start()
end

function OverseaManagePersonnelRoleCell:OnBtnDelClick()
    ---点击的事件执行
    if self.callBack then
        self.callBack(true)
    end
end

function OverseaManagePersonnelRoleCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManagePersonnelRoleCell